using LocalChat;
int checks=0;void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);checks++;Console.WriteLine("PASS "+name);}
var profiles=ExperimentalProfiles.All;Check(profiles.Length==3,"three real templates embedded");Check(profiles.Select(p=>p.Id).Order().SequenceEqual(new[]{"dan","dan6","stan"}),"known distinct IDs");Check(profiles.All(p=>p.Prompt.Length>1000&&p.Prompt.Length<6000),"full long templates retained");Check(profiles.All(p=>p.Source.Contains("4b7761c2108446043012549cbe8f7c942cabb26d")),"pinned source revision");Check(profiles.All(p=>p.Prompt.Contains("{generator.name}")),"source placeholder retained in resource");
var s=new Settings{SystemPrompt="CUSTOM",ModelPath="existing",ContextTokens=512};Check(ExperimentalProfiles.ApplyDefaults(s),"one-time default migration");Check(s.ExperimentalProfileId=="","current migration keeps experimental text profile disabled");Check(s.ContextTokens==512,"disabled profile does not rewrite Air context");Check(ExperimentalProfiles.CanUseModelTools(s),"disabled experimental profile permits model tools");s.ExperimentalProfileId="dan6";ExperimentalProfiles.PrepareContext(s);Check(s.ContextTokens==2048,"explicitly selected long profile prepares Air context");Check(s.SystemPrompt=="CUSTOM"&&s.ModelPath=="existing","weights and saved system prompt unchanged");Check(!ExperimentalProfiles.CanUseModelTools(s),"automatic model tools disabled in experiment");
const string task="Напиши тест. Literal {generator.name} stays in task.";string full=ExperimentalProfiles.Wrap(s,task);Check(full.EndsWith(task),"actual request retained verbatim");Check(full.Contains("Hello local assistant"),"template placeholder substituted");Check(full.Contains("Do not claim external actions occurred"),"no fake tool action instruction wrapper");Check(ExperimentalProfiles.Wrap(s,task,true)==task,"team stage not wrapped");Check(!ExperimentalProfiles.Active(s,true),"team not marked active");Check(ExperimentalProfiles.Active(s,false),"ordinary chat experiment active");
s.ExperimentalProfileId="";Check(ExperimentalProfiles.Wrap(s,task)==task,"off means no wrapper");Check(ExperimentalProfiles.CanUseModelTools(s),"off restores original tools policy");Check(!ExperimentalProfiles.ApplyDefaults(s)&&s.ExperimentalProfileId=="","manual disabling persists after migration");ExperimentalProfiles.Validate("");Check(true,"empty selection accepted");bool bad=false;try{ExperimentalProfiles.Validate("invalid");}catch(ArgumentException){bad=true;}Check(bad,"unknown profile rejected");
foreach(string id in new[]{"dan6","dan","stan"}){s.ExperimentalProfileId=id;var prompt=ExperimentalProfiles.Wrap(s,"TASK");Check(prompt.Length>profiles.First(p=>p.Id==id).Prompt.Length&&prompt.EndsWith("TASK"),"full profile plus task: "+id);}
s=new Settings{Mode=1,ContextTokens=512};ExperimentalProfiles.ApplyDefaults(s);Check(s.ContextTokens==512,"LM Studio server context not rewritten");s=new Settings{Mode=2,ContextTokens=1024};ExperimentalProfiles.ApplyDefaults(s);Check(s.ContextTokens==1024,"GGUF context stays user-selected");Console.WriteLine($"{checks} experimental profile checks passed");
